CREATE TABLE IF NOT EXISTS career_goals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','paused','completed')), priority int NOT NULL DEFAULT 3 CHECK (priority BETWEEN 1 AND 5), target_date date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE skills ADD COLUMN IF NOT EXISTS level int NOT NULL DEFAULT 3;
ALTER TABLE skills ADD COLUMN IF NOT EXISTS target_level int;
ALTER TABLE skills ADD COLUMN IF NOT EXISTS evidence_summary text NOT NULL DEFAULT '';
ALTER TABLE skills ADD COLUMN IF NOT EXISTS category text;
ALTER TABLE skills ADD CONSTRAINT skills_level_range CHECK (level BETWEEN 1 AND 5);
ALTER TABLE skills ADD CONSTRAINT skills_target_level_range CHECK (target_level IS NULL OR target_level BETWEEN 1 AND 5);
CREATE TABLE IF NOT EXISTS learning_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, skill text NOT NULL DEFAULT '', type text NOT NULL DEFAULT 'topic', status text NOT NULL DEFAULT 'planned' CHECK (status IN ('planned','in_progress','completed','dropped')), url text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', due_date date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS network_contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, company text NOT NULL DEFAULT '', role text NOT NULL DEFAULT '', profile_url text NOT NULL DEFAULT '', relationship text NOT NULL DEFAULT '', last_contacted_at timestamptz, follow_up_at timestamptz, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS startup_ideas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, problem text NOT NULL DEFAULT '', customer text NOT NULL DEFAULT '', hypothesis text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'idea' CHECK (status IN ('idea','researching','validating','building','paused','closed')), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS career_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, area text NOT NULL DEFAULT 'career', status text NOT NULL DEFAULT 'todo' CHECK (status IN ('todo','in_progress','done','dismissed')), priority int NOT NULL DEFAULT 3 CHECK (priority BETWEEN 1 AND 5), due_at timestamptz, source_agent text NOT NULL DEFAULT '', related_entity_id uuid, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS career_recommendations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agent_name text NOT NULL, title text NOT NULL, rationale text NOT NULL DEFAULT '', action text NOT NULL DEFAULT '', priority int NOT NULL DEFAULT 3 CHECK (priority BETWEEN 1 AND 5), status text NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed','accepted','dismissed','completed')), payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agent_name text NOT NULL, trigger text NOT NULL DEFAULT 'manual', status text NOT NULL DEFAULT 'running' CHECK (status IN ('running','completed','failed')), model text NOT NULL DEFAULT '', prompt_version text NOT NULL DEFAULT 'v1', input jsonb NOT NULL DEFAULT '{}'::jsonb, output jsonb NOT NULL DEFAULT '{}'::jsonb, error text NOT NULL DEFAULT '', started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE INDEX IF NOT EXISTS idx_career_tasks_status ON career_tasks(status, priority);
CREATE INDEX IF NOT EXISTS idx_recommendations_status ON career_recommendations(status, priority);
CREATE INDEX IF NOT EXISTS idx_agent_runs_started ON agent_runs(started_at DESC);
INSERT INTO career_goals(title,description,priority) SELECT 'Build next-level career optionality','Maintain strong Principal/Architect, AI Security, leadership, advisory and founder paths without prematurely choosing one.',1 WHERE NOT EXISTS (SELECT 1 FROM career_goals);
INSERT INTO skills(name,category,level,target_level,evidence_summary) VALUES ('Distributed Systems','architecture',5,5,'Architected and built cloud-native distributed systems and security platforms.'),('Kubernetes','platform',5,5,'Extensive production Kubernetes/EKS and operator/platform experience.'),('Cloud Security','security',5,5,'Built CNAPP, CSPM, DSPM and cloud posture capabilities.'),('AI Security','security',4,5,'Built AI security/asset-management capabilities across models, agents, MCP and identities.'),('AI Agent Architecture','ai',3,5,'Hands-on agent, MCP, ADK and A2A-compatible chatbot work.'),('Technical Leadership','leadership',4,5,'Architect-level ownership across products and cross-functional technical decisions.'),('Data Platforms','data',5,5,'Spark, Delta Lake, Databricks, Snowflake, ClickHouse and large-scale data pipelines.') ON CONFLICT (name) DO NOTHING;